package dev.shadw.asgard.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Jötunn with its own model and texture. Generated by shadw-mod mob. */
public class JotunnRenderer extends MobRenderer<Jotunn, JotunnModel.State, JotunnModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/jotunn.png");

	public JotunnRenderer(EntityRendererProvider.Context context) {
		super(context, new JotunnModel(context.bakeLayer(JotunnModel.LAYER)), 0.9F);
	}

	@Override
	public JotunnModel.State createRenderState() {
		return new JotunnModel.State();
	}

	@Override
	public void extractRenderState(Jotunn entity, JotunnModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(JotunnModel.State state) {
		return TEXTURE;
	}
}
